"""Embedded video cannot receive pointer/keyboard input; app controls still work."""
from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844});page.route('**/player-test',lambda r:r.fulfill(content_type='text/html',body='<style>.podcast-player{height:220px}.podcast-player iframe{width:100%;height:100%}</style><main></main>'));page.goto('http://127.0.0.1:8000/player-test')
 page.evaluate("""async()=>{window.plays=0;window.pauses=0;window.escaped=false;window.YT={Player:function(holder,config){const iframe=document.createElement('iframe');iframe.srcdoc='<a href="https://www.youtube.com/" target="_top" style="display:block;height:200px" onclick="parent.escaped=true;return false">YouTube</a>';holder.replaceWith(iframe);this.playVideo=()=>window.plays++;this.pauseVideo=()=>window.pauses++;this.destroy=()=>{};setTimeout(()=>config.events.onReady(),0);}};const {mountCompactYouTube}=await import('./cbse-youtube-player.js');await mountCompactYouTube(document.querySelector('main'),'abcdefghijk');} """)
 play=page.get_by_role('button',name='Play',exact=True);play.wait_for();play.click();frame=page.locator('.podcast-player');assert frame.evaluate('(n)=>n.inert');assert frame.evaluate('(n)=>getComputedStyle(n).pointerEvents')=='none';box=frame.bounding_box()
 for i in range(4):page.mouse.click(box['x']+40,box['y']+40)
 assert page.evaluate('escaped')==False;assert page.url.endswith('/player-test');assert page.evaluate('plays')==1;play.focus();page.keyboard.press('Tab');assert page.get_by_role('button',name='Pause').evaluate('(n)=>n===document.activeElement');page.keyboard.press('Enter');assert page.evaluate('pauses')==1;b.close()
print('PASS video taps cannot activate embedded links; app Play/Pause and keyboard controls still work')
